<span class="line"><span style="color:#ABB2BF;">    log_sum_exp </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> max_logit </span><span style="color:#56B6C2;">+</span><span style="color:#ABB2BF;"> math.</span><span style="color:#61AFEF;">log</span><span style="color:#ABB2BF;">(</span><span style="color:#56B6C2;">sum</span><span style="color:#ABB2BF;">(math.</span><span style="color:#61AFEF;">exp</span><span style="color:#ABB2BF;">(z) </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> z </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> shifted))</span></span>
